/* ═════════ GATEWAY FILES (-86, 2026-11-20) ═════════
   Built gateways live in gateways/<key>.js and load on demand (core: gwEnsure). Until a file arrives, GATEWAYS[key] and
   its ZONES are light stubs from the generated index below (flagged _stub), so bands, rows, search and Events work from
   the first frame. A loaded file simply overwrites its stubs. gxEvents registers a gateway's events once, whichever of
   the index or the file runs. */
function gxStub(gws, zones){ for(const k in gws) if(!GATEWAYS[k]) GATEWAYS[k]=gws[k]; for(const k in zones) if(!ZONES[k]) ZONES[k]=zones[k]; }
function gxEvents(gw, list){ const add=list.map(e=>Object.assign({gw}, e)); let at=-1; for(let i=EVENTS_FEED.length-1;i>=0;i--) if(EVENTS_FEED[i].gw===gw){ EVENTS_FEED.splice(i,1); at=i; } if(at<0) EVENTS_FEED.push(...add); else EVENTS_FEED.splice(at,0,...add); }
